MATCH (source:PlantItem {no_inflow: true})-[:line_to*1..]->(:PlantItem {tag: 'TK-104'})
RETURN DISTINCT source.tag AS tag
ORDER BY tag;

MATCH (p:PlantItem {tag: 'P-201A'}), (v:Valve), (e:Equipment)
WHERE EXISTS { (p)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(e) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'TK-104'}), (b:PlantItem {tag: 'P-101A'})
MATCH (v:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
WITH collect(DISTINCT v.tag) AS valve_tags
RETURN size(valve_tags) AS valve_count, valve_tags

MATCH (e:Equipment)-[:measured_by]->(i:ProcessInstrumentationFunction {loop_tag: 'LI-1031'})
RETURN DISTINCT e.tag AS tag
ORDER BY tag;

MATCH (v:Valve)-[:line_to*1..]->(t:PlantItem {tag: 'TK-104'})
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'TK-101'}), (b:PlantItem {tag: 'P-101A'})
RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS {
         MATCH (a) ((x:PlantItem)-[:line_to]->(y:PlantItem)
           WHERE x.tag <> 'PGV-1011' AND y.tag <> 'PGV-1011')+ (b)
       } AS reachable

MATCH (a:PlantItem {tag: 'P-201A'}), (b:PlantItem {tag: 'V-201'})
RETURN EXISTS {
  MATCH (a)
  ((x:PlantItem WHERE x.tag <> 'CHV-2002')-[:line_to]->(y:PlantItem WHERE y.tag <> 'CHV-2002'))+
  (b)
} AS can_flow_without_CHV_2002

MATCH (e:PlantItem {tag: 'TK-104'})-[:measured_by]->(i:PlantItem)
RETURN DISTINCT i.tag AS tag
ORDER BY tag;

MATCH (p:PlantItem:Pump {tag: 'P-101A'})-[:line_to*1..]->(v:PlantItem:Valve)-[:line_to*1..]->(e:PlantItem:Equipment)
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'P-201A'}), (b:PlantItem {tag: 'V-201'}), (v:Valve)
WHERE v <> a AND v <> b
  AND EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (v:Valve)-[:line_to*1..]->(:PlantItem {tag: 'TK-103'})
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (e:PlantItem {tag: 'P-201A'})-[:measured_by]->(i:PlantItem)
RETURN DISTINCT i.tag AS tag
ORDER BY tag;

MATCH (head:ProcessInstrumentationFunction {loop_tag: 'LSHH-1002'})-[:send_signal_to*1..]->(actuator:PlantItem {kind: 'actuator'})-[:control]->(valve:Valve)
RETURN DISTINCT valve.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'TK-101'}), (b:PlantItem {tag: 'P-101B'}), (v:PlantItem:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (a:PlantItem {tag: 'TK-101'}), (b:PlantItem {tag: 'V-201'}), (v:PlantItem:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (p:PlantItem:RotaryPump {unit_id: '1'})
RETURN p.tag AS tag
ORDER BY tag;
